// Printers draw barcode interpretation lines in font A, a 5x9 dot bitmap font
// magnified by the ^BY module width. Glyphs are 5 dots wide with 1 dot of
// spacing; rows 0-6 hold capitals and digits, rows 7-8 descenders.
const (
	fontACols    = 5
	fontAPitch   = fontACols + 1
	fontACapRows = 7
)

