// fontAWidth is the width of text set in font A at magnification mag, from
// the first dot of the first glyph to the last dot of the last one.
func fontAWidth(text string, mag int) int {
	n := len([]rune(text))
	if n == 0 {
		return 0
	}
	return (n*fontAPitch - 1) * mag
}

// drawFontA draws text in font A with its top-left cell corner at (x, y),
// each dot magnified to a mag x mag square. Characters without a glyph leave
// a blank cell.
func (c *canvas) drawFontA(text string, x, y, mag int, col color.RGBA) {
	var rects []image.Rectangle
	for i, r := range []rune(text) {
		gx := x + i*fontAPitch*mag
		for row, bits := range strings.Fields(fontAGlyphs[r]) {
			for colIdx := 0; colIdx < len(bits); {
				if bits[colIdx] != '#' {
					colIdx++
					continue
				}
				// Merge a run of dots into one rectangle.
				end := colIdx
				for end < len(bits) && bits[end] == '#' {
					end++
				}
				rects = append(rects, image.Rect(gx+colIdx*mag, y+row*mag, gx+end*mag, y+(row+1)*mag))
				colIdx = end
			}
		}
	}
	for _, rc := range rects {
		for py := rc.Min.Y; py < rc.Max.Y; py++ {
			for px := rc.Min.X; px < rc.Max.X; px++ {
				c.img.Set(px, py, col)
			}
		}
	}
	c.recordRects(PaintBlack, rects...)
}
